"""Vista ejecutiva compacta: HTML/CSS calculado desde datos SAP, sin indicadores fijos."""
import html

def render(data):
    e=lambda v:html.escape(str(v))
    q=lambda v:f'{int(round(v)):,}'.replace(',','.')
    cash=lambda v:'$ '+f'{float(v):,.2f}'.replace(',','X').replace('.',',').replace('X','.')
    initial,inc,stock,out,nc,phys,pending=[data[k] for k in ('initial','in_qty','stock','out_qty','nc_units','physical_units','pending_units')]
    available=initial+inc if initial is not None else None
    classified=stock+out+nc+phys+pending
    delta=(available-classified) if available is not None else None
    items=[('Stock actual',stock,'#05495e'),('Egresos desde enero',out,'#48b0e0'),('NC recuperadas',nc,'#f7bd08'),('Nuevas / reparadas',phys,'#37b7ae'),('Solicitudes abiertas',pending,'#ef615b')]
    total=sum(v for _,v,_ in items)
    stop=0;grad=[]
    for label,v,color in items:
        nextstop=stop+100*v/total if total else stop
        grad.append(f'{color} {stop:.3f}% {nextstop:.3f}%');stop=nextstop
    legend=''.join(f'<div class="eleg"><span class="dot" style="background:{color}"></span><span>{e(label)}</span><strong>{q(v)} u.</strong></div>' for label,v,color in items)
    variance=(stock-initial)/initial*100 if initial else None
    monthnames=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']
    trend=data['trend'];maxv=max([1]+[max(x,y) for x,y in trend])
    bars=''.join(f'<div class="emonth"><div class="ebars"><div class="ebar" title="Ingresos: {q(a)}" style="height:{max(2,100*a/maxv):.2f}%;background:#07576b"></div><div class="ebar" title="Egresos: {q(b)}" style="height:{max(2,100*b/maxv):.2f}%;background:#4ab6e2"></div></div><span>{monthnames[i]}</span></div>' for i,(a,b) in enumerate(trend) if i<=data['month']-1)
    status='Sin diferencias (0 u.)' if delta==0 else f'Diferencia: {q(delta)} u.' if delta is not None else 'No disponible'
    statusclass='ok' if delta==0 else 'warn'
    return f'''<div class="exec61">
    <div class="etop"><div class="emark"><strong>YMK</strong><small>HOGAR</small></div><div class="etitle"><h2>Postventa – Depósito 055</h2><p>Resultado de gestión y recuperación económica</p></div><div class="eupdate">CORTE: {e(data['period'])}<small>Fuentes SAP · Stock · Movimientos · NC · Ventas</small></div></div>
    <section class="epanel"><div class="etab">◈ &nbsp;01 · PUNTO DE PARTIDA Y EVOLUCIÓN DE LA GESTIÓN</div><div class="estart">
    <div class="estat"><small>Stock inicial</small><strong>{q(initial) if initial is not None else 'N/D'} <em>u.</em></strong></div><b class="eoperator">+</b>
    <div class="estat"><small>Ingresos desde abril</small><strong>{q(inc)} <em>u.</em></strong></div><b class="eoperator">=</b>
    <div class="estat primary"><small>Total gestionado</small><strong>{q(available) if available is not None else 'N/D'} <em>u.</em></strong></div><div class="eseparator"></div>
    <div class="estat"><small>Stock actual</small><strong>{q(stock)} <em>u.</em></strong></div><div class="estat green"><small>Variación del stock</small><strong>{f'{variance:+.1f}%'.replace('.',',') if variance is not None else 'N/D'}</strong><span>{q(stock-initial) if initial is not None else 'N/D'} unidades</span></div></div></section>
    <div class="etwocol"><section class="epanel"><div class="etab">◉ &nbsp;02 · DESTINO DE LA MERCADERÍA ({q(total)} UNIDADES)</div><div class="edest"><div class="edonut" style="background:conic-gradient({','.join(grad)})"><div class="ehole"><strong>{q(total)}</strong><small>unidades</small></div></div><div class="elegend">{legend}<div class="esub">Egresos: {q(data['out_other'])} a otros destinos · {q(data['sent'])} al 109</div></div></div><div class="eecorow"><span><b>Pagos por Reparaciones fuera de DOA</b></span><strong style="color:#c62828">{('-'+cash(data['doa_expense'])) if data.get('doa_expense') is not None else 'Archivo Finanzas pendiente'}</strong></div><div class="eecorow"><span><b>Scrap · gasto anual manual</b></span><strong style="color:#c62828">-{cash(data['scrap_expense'])}</strong></div></section>
    <section class="epanel"><div class="etab">◉ &nbsp;03 · RESULTADO ECONÓMICO DE LA GESTIÓN</div><div class="eeco">
    <div class="eecorow"><span><b>Recuperación mediante NC</b><small>{q(nc)} unidades</small></span><strong>{cash(data['nc_value'])}</strong></div>
    <div class="eecorow"><span><b>Productos nuevos / reparados</b><small>{q(phys)} unidades</small></span><strong>{cash(data['physical_value'])}</strong></div>
    <div class="eecorow"><span><b>Retornos del Almacén de Reparación 109</b><small>{q(data['ret'])} unidades · informativo</small></span><strong>{cash(data['ret_value'])}</strong></div>
    <div class="eecototal"><span>Volumen económico gestionado<small>NC + nuevas/reparadas + retornos 109 · incluye posible superposición</small></span><strong>{cash(data['nc_value']+data['physical_value']+data['ret_value'])}</strong></div>
    <div class="eecototal"><span>Recuperación clasificada<small>NC + nuevas/reparadas · sin duplicar retornos 109</small></span><strong>{cash(data['nc_value']+data['physical_value'])}</strong></div>
    
    <div class="einfo">El volumen económico gestionado no equivale a recupero neto: los retornos del 109 pueden superponerse con las recuperaciones clasificadas.</div></div></section></div>
    <section class="epanel econc"><div class="etab">⚖ &nbsp;04 · CONCILIACIÓN DE UNIDADES</div><div class="econcile"><div><small>Total gestionado</small><strong>{q(available) if available is not None else 'N/D'} u.</strong></div><b>−</b><div><small>Total clasificado</small><strong>{q(classified)} u.</strong></div><b>=</b><div class="estatus {statusclass}">{e(status)}</div><div class="escrap"><small>Chatarra / scrap · incluida en egresos</small><strong>66 u. · egreso incluido en el gráfico</strong></div></div></section>
    <div class="etwocol ebottom"><section class="epanel"><div class="etab">▥ &nbsp;05 · EVOLUCIÓN MENSUAL DE MOVIMIENTOS</div><div class="echart"><div class="ebarplot">{bars}</div><div class="ekey"><span><i style="background:#07576b"></i>Ingresos</span><span><i style="background:#4ab6e2"></i>Egresos</span></div></div></section>
    <section class="epanel eresults"><div class="etab">★ &nbsp;PRINCIPALES RESULTADOS DE LA GESTIÓN</div><div class="eresultgrid"><div><span>↓</span><strong>{q(initial-stock) if initial is not None else 'N/D'} u.</strong><small>Reducción del stock inicial</small></div><div><span>$</span><strong>{cash(data['nc_value']+data['physical_value'])}</strong><small>Recuperación económica clasificada</small></div><div><span>↺</span><strong>{q(data['ret'])} u.</strong><small>Retornos Almacén 109</small></div></div></section></div>
    <p class="efoot">Conciliación aritmética según categorías operativas; no reemplaza la trazabilidad documental SAP. Los movimientos del 109 y el scrap se informan sin duplicarlos.</p></div>'''

CSS='''<style>
.exec61{font-family:Arial,Helvetica,sans-serif;color:#07374c;font-size:13px;line-height:1.25}.exec61 *{box-sizing:border-box}.exec61 .etop{display:flex;align-items:center;gap:19px;background:linear-gradient(110deg,#022f40,#075a74);color:white;padding:12px 22px;border-radius:12px;margin:0 0 8px;min-height:77px}.exec61 .emark{border-right:3px solid #ffc107;padding-right:18px;display:flex;flex-direction:column;line-height:.85}.exec61 .emark strong{font-size:29px;font-style:italic;letter-spacing:-2px;color:white}.exec61 .emark small{font-size:12px;letter-spacing:3px;margin-top:7px}.exec61 .etitle{flex:1}.exec61 .etitle h2{font-size:24px!important;color:white!important;margin:0!important;line-height:1.2}.exec61 .etitle p{color:#d5e8f0;margin:4px 0 0}.exec61 .eupdate{text-align:right;font-size:11px}.exec61 .eupdate small{display:block;color:#d6e7ec;margin-top:5px}.exec61 .epanel{background:#fff;border:1px solid #d6e5ed;border-radius:14px;padding:8px 10px 10px;box-shadow:0 2px 7px #07374c0d;min-width:0}.exec61 .etab{background:linear-gradient(90deg,#023c51,#025b72);border-radius:8px;color:white;font-size:12px;font-weight:800;padding:8px 12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:9px}.exec61 .estart{display:flex;align-items:stretch;justify-content:space-around;gap:9px}.exec61 .estat{flex:1;text-align:center;background:#eaf3f8;border-radius:9px;padding:9px 4px;min-width:0}.exec61 .estat small{display:block;font-size:11px;font-weight:700}.exec61 .estat strong{display:block;font-size:clamp(19px,2vw,29px);font-weight:900;white-space:nowrap;margin-top:5px}.exec61 .estat strong em{font-size:12px;font-style:normal}.exec61 .estat span{display:block;font-size:10px}.exec61 .estat.primary{background:linear-gradient(#05657d,#023a50);color:white;flex:1.2}.exec61 .estat.green{background:#e2f7e4;color:#187e36}.exec61 .eoperator{align-self:center;font-size:23px}.exec61 .eseparator{width:1px;background:#b5c9d4;margin:3px 3px}.exec61 .etwocol{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:9px}.exec61 .edest{display:flex;align-items:center;gap:15px;min-height:190px}.exec61 .edonut{width:177px;height:177px;min-width:177px;border-radius:50%;display:flex;align-items:center;justify-content:center}.exec61 .ehole{width:100px;height:100px;border-radius:50%;background:white;display:flex;flex-direction:column;align-items:center;justify-content:center}.exec61 .ehole strong{font-size:25px}.exec61 .ehole small{font-size:12px}.exec61 .elegend{flex:1;min-width:0}.exec61 .eleg{display:grid;grid-template-columns:10px 1fr auto;gap:6px;align-items:center;padding:5px 0;border-bottom:1px solid #edf2f4;font-size:11px}.exec61 .eleg strong{white-space:nowrap}.exec61 .dot{height:9px;width:9px;border-radius:50%}.exec61 .esub{background:#edf5fa;border-radius:5px;padding:6px;margin-top:5px;font-size:10px}.exec61 .eeco{padding:1px 5px}.exec61 .eecorow{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 2px;border-bottom:1px solid #e7eef2}.exec61 .eecorow span b{display:block;font-size:12px}.exec61 .eecorow small,.exec61 .eecototal small{display:block;font-size:10px;color:#637e8b;margin-top:2px}.exec61 .eecorow strong{white-space:nowrap;font-size:13px}.exec61 .eecototal{display:flex;justify-content:space-between;align-items:center;gap:8px;background:#e8f3f8;border-radius:8px;padding:11px;margin-top:8px;font-weight:800}.exec61 .eecototal strong{background:#03536a;color:white;padding:8px;border-radius:7px;font-size:15px;white-space:nowrap}.exec61 .einfo{font-size:10px;color:#607f8e;padding:6px 3px}.exec61 .econc{margin-top:9px}.exec61 .econcile{display:flex;align-items:center;gap:10px;justify-content:space-between}.exec61 .econcile>div:not(.estatus):not(.escrap){display:flex;flex-direction:column;background:#eaf3f8;border-radius:8px;padding:6px 12px;text-align:center;min-width:105px}.exec61 .econcile small{font-size:10px}.exec61 .econcile strong{font-size:15px}.exec61 .estatus{padding:10px;border-radius:8px;font-weight:800;white-space:nowrap}.exec61 .estatus.ok{background:#e3f7e5;color:#197d36}.exec61 .estatus.warn{background:#fff1df;color:#a35200}.exec61 .escrap{border-left:1px solid #d8e4eb;padding-left:12px;display:flex;flex-direction:column}.exec61 .ebottom{margin-top:9px}.exec61 .echart{padding:7px 9px}.exec61 .ebarplot{height:145px;display:flex;align-items:flex-end;justify-content:space-around;border-bottom:1px solid #b7cbd4;background:repeating-linear-gradient(to top,transparent 0,transparent 28px,#e9f0f3 29px);gap:4px}.exec61 .emonth{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:end;flex:1}.exec61 .ebars{height:122px;width:100%;display:flex;align-items:end;justify-content:center;gap:3px}.exec61 .ebar{width:30%;min-width:5px;max-width:17px;border-radius:2px 2px 0 0}.exec61 .emonth span{font-size:10px;padding-top:3px}.exec61 .ekey{display:flex;justify-content:center;gap:17px;font-size:10px;margin-top:10px}.exec61 .ekey i{display:inline-block;width:10px;height:10px;margin-right:5px}.exec61 .eresults{background:#fff9e7}.exec61 .eresultgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:3px;padding:14px 4px}.exec61 .eresultgrid>div{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;padding:0 8px;border-right:1px solid #d7d4c7}.exec61 .eresultgrid>div:last-child{border:0}.exec61 .eresultgrid span{color:#bc8a00;font-size:24px;font-weight:bold}.exec61 .eresultgrid strong{font-size:clamp(12px,1.4vw,19px);color:#6b4800;white-space:nowrap}.exec61 .eresultgrid small{font-size:11px}.exec61 .efoot{font-size:10px;color:#68818c;margin:7px 3px}@media(max-width:1100px){.exec61 .etwocol{grid-template-columns:1fr}.exec61 .econcile{flex-wrap:wrap}.exec61 .edest{justify-content:center}}@media(max-width:680px){.exec61 .etop{flex-wrap:wrap}.exec61 .eupdate{display:none}.exec61 .estart{flex-wrap:wrap}.exec61 .estat{min-width:29%}.exec61 .eoperator,.exec61 .eseparator{display:none}.exec61 .edest{flex-wrap:wrap}.exec61 .eecorow,.exec61 .eecototal{flex-wrap:wrap}}
</style>'''
